class Solution:
    def findMatchingSubmatrix(self, board: List[List[int]], pattern: List[str]) -> List[int]:
        R, C, P, Q = len(board), len(board[0]), len(pattern), len(pattern[0])
        for r in range(R - P + 1):
            for c in range(C - Q + 1):
                l2d, d2l = {}, {}
                ok = True
                for i in range(P):
                    for j in range(Q):
                        ch, val = pattern[i][j], board[r+i][c+j]
                        if ch.isdigit():
                            if int(ch) != val: ok = False; break
                        else:
                            if ch in l2d:
                                if l2d[ch] != val: ok = False; break
                            elif val in d2l:
                                ok = False; break
                            else:
                                l2d[ch] = val; d2l[val] = ch
                    if not ok: break
                if ok: return [r, c]
        return [-1, -1]

