class Solution {
public:
    vector<int> findMatchingSubmatrix(vector<vector<int>>& board, vector<string>& pattern) {
        int R = board.size(), C = board[0].size(), P = pattern.size(), Q = pattern[0].size();
        for (int r = 0; r + P <= R; r++)
            for (int c = 0; c + Q <= C; c++) {
                unordered_map<char,int> l2d;
                unordered_map<int,char> d2l;
                bool ok = true;
                for (int i = 0; i < P && ok; i++)
                    for (int j = 0; j < Q && ok; j++) {
                        char ch = pattern[i][j]; int val = board[r+i][c+j];
                        if (isdigit(ch)) { if (ch - '0' != val) ok = false; }
                        else {
                            auto it = l2d.find(ch);
                            if (it != l2d.end()) { if (it->second != val) ok = false; }
                            else if (d2l.count(val)) ok = false;
                            else { l2d[ch] = val; d2l[val] = ch; }
                        }
                    }
                if (ok) return {r, c};
            }
        return {-1, -1};
    }
};

