class Solution {
    public int[] findMatchingSubmatrix(int[][] board, String[] pattern) {
        int R = board.length, C = board[0].length, P = pattern.length, Q = pattern[0].length();
        for (int r = 0; r + P <= R; r++)
            for (int c = 0; c + Q <= C; c++) {
                Map<Character,Integer> l2d = new HashMap<>();
                Map<Integer,Character> d2l = new HashMap<>();
                boolean ok = true;
                for (int i = 0; i < P && ok; i++)
                    for (int j = 0; j < Q && ok; j++) {
                        char ch = pattern[i].charAt(j); int val = board[r+i][c+j];
                        if (Character.isDigit(ch)) {
                            if (ch - '0' != val) ok = false;
                        } else if (l2d.containsKey(ch)) {
                            if (l2d.get(ch) != val) ok = false;
                        } else if (d2l.containsKey(val)) ok = false;
                        else { l2d.put(ch, val); d2l.put(val, ch); }
                    }
                if (ok) return new int[]{r, c};
            }
        return new int[]{-1, -1};
    }
}

