var findMatchingSubmatrix = function(board, pattern) {
    const R = board.length, C = board[0].length, P = pattern.length, Q = pattern[0].length;
    for (let r = 0; r + P <= R; r++)
        for (let c = 0; c + Q <= C; c++) {
            const l2d = {}, d2l = {};
            let ok = true;
            outer:
            for (let i = 0; i < P; i++)
                for (let j = 0; j < Q; j++) {
                    const ch = pattern[i][j], val = board[r+i][c+j];
                    if (ch >= '0' && ch <= '9') {
                        if (+ch !== val) { ok = false; break outer; }
                    } else if (ch in l2d) {
                        if (l2d[ch] !== val) { ok = false; break outer; }
                    } else if (val in d2l) { ok = false; break outer; }
                    else { l2d[ch] = val; d2l[val] = ch; }
                }
            if (ok) return [r, c];
        }
    return [-1, -1];
};
